I=("WHEAT","CARROT","TOMATO","STRAWBERRY","MELON","EGG","MILK","WOOL","FERTILIZER");C=I[:5];N=("GOOSE","COW","SHEEP")
def F(o,p):
 f=o["farms"];w=f[p];v=f[1-p];r=o.get("private") or {};m=o.get("market") or {};P=m.get("prices") or {};Z=m.get("inventory") or {};S=r.get("shed") or {};E=r.get("seeds") or {};V=r.get("inventories") or [];B=w.get("tiles") or [];c={x:0 for x in C+N+("WEED",)};u=[]
 for i,a in enumerate([w.get("farmer",[4,4])]+(w.get("hands") or [])):
  q=V[i] if i<len(V) and isinstance(V[i],dict) else {};x,y=map(int,a);t=B[y][x] if 0<=y<len(B) and 0<=x<len(B[y]) else None
  if isinstance(t,dict):l=(str(t.get("kind") or ""),str(t.get("crop") or ""),str(t.get("animal") or ""),int(t.get("yield_units",0) or 0),int(bool(t.get("watered_today"))),int(bool(t.get("fed_today"))),int(bool(t.get("cared_today"))))
  else:l=(str(t or ""),"","",0,0,0,0)
  u.append((x,y,sum(int(k or 0) for k in q.values()),int(q.get("WHEAT",0) or 0),int(q.get("FERTILIZER",0) or 0),l))
 for R in B:
  for t in R:
   if isinstance(t,dict):
    k=t.get("crop") or t.get("animal") or ("WEED" if t.get("kind")=="WEED" else None)
    if k in c:c[k]+=1
 return {"m":float(w.get("money",0) or 0),"om":float(v.get("money",0) or 0),"h":len(w.get("hands") or []),"oh":len(v.get("hands") or []),"q":len(w.get("unlocked_quadrants") or []),"oq":len(v.get("unlocked_quadrants") or []),"p":[float(P.get(x,0) or 0) for x in I],"z":[float(Z.get(x,0) or 0) for x in I],"s":[int(S.get(x,0) or 0) for x in I],"e":[int(E.get(x,0) or 0) for x in C],"b":[c[x] for x in C+N+("WEED",)],"u":u,"shop":sorted((o.get("town") or {}).get("unlocked_shops") or [])}
def dist(a,b):
 d=10*abs(math.log1p(a["m"])-math.log1p(b["m"]))+8*abs(math.log1p(a["om"])-math.log1p(b["om"]))+100*abs(a["h"]-b["h"])+30*abs(a["oh"]-b["oh"])+140*abs(a["q"]-b["q"])+30*abs(a["oq"]-b["oq"])+20*len(set(a["shop"])^set(b["shop"]))
 d+=sum(abs(x-y)*.04 for x,y in zip(a["p"],b["p"]))+sum(abs(x-y)*.01 for x,y in zip(a["z"],b["z"]))+sum(abs(x-y)*.35 for x,y in zip(a["s"],b["s"]))+sum(abs(x-y)*2 for x,y in zip(a["e"],b["e"]))+sum(abs(x-y)*7 for x,y in zip(a["b"],b["b"]))
 d+=300*abs(len(a["u"])-len(b["u"]))
 for x,y in zip(a["u"],b["u"]):d+=35*(abs(x[0]-y[0])+abs(x[1]-y[1]))+.2*abs(x[2]-y[2])+abs(x[3]-y[3])+2*abs(x[4]-y[4])+120*(x[5][:3]!=tuple(y[5][:3]))+3*abs(x[5][3]-y[5][3])+15*sum(i!=j for i,j in zip(x[5][4:],y[5][4:]))
 return d
def agent(o,c=None):
 p=int(o.get("player",0));s=min(int(o.get("step",0)),718);f=F(o,p);q=min((t[s] for t in D if s<len(t)),key=lambda x:dist(f,x[0]))[1];q=copy.deepcopy(q);q["hands"]=(q.get("hands") or [])[:len(o["farms"][p].get("hands") or [])];return q
act=agent
